<?php
namespace Tests\Feature;
use App\Models\Product;use App\Models\ProductBatch;use App\Models\User;use App\Services\AccountingReportService;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\DB;use Tests\TestCase;
class ErpExpansionFoundationTest extends TestCase{
 use RefreshDatabase; private User $admin;
 protected function setUp():void{parent::setUp();$this->seed();$this->admin=User::factory()->create(['role'=>1,'force_change_password'=>false]);$this->actingAs($this->admin,'sanctum');}
 public function test_report_catalog_query_saved_report_and_unknown_columns_are_safe():void{$p=Product::factory()->create(['name'=>'Explorer Drug']);$catalog=$this->getJson('/api/reports/catalog')->assertOk();$this->assertNotContains('products',collect($catalog->json('data'))->pluck('key'));$this->postJson('/api/reports/query',['report_key'=>'products','filters'=>['search'=>'Explorer'],'columns'=>['id','name'],'sort'=>'name'])->assertOk()->assertJsonPath('data.meta.total',1)->assertJsonPath('data.rows.0.id',$p->id);$this->postJson('/api/reports/saved',['name'=>'My products','report_key'=>'products','filters'=>['search'=>'Explorer'],'visible_columns'=>['id','name']])->assertUnprocessable();$this->postJson('/api/reports/query',['report_key'=>'products','columns'=>['password']])->assertUnprocessable();}
 public function test_opening_inventory_posts_real_stock_and_balanced_journal():void{$p=Product::factory()->create();$id=$this->postJson('/api/opening-balances',['effective_date'=>now()->toDateString(),'lines'=>[['type'=>'inventory','product_id'=>$p->id,'batch_number'=>'OPEN-1','expiry_date'=>now()->addYear()->toDateString(),'quantity'=>10,'unit_cost'=>3,'sale_price'=>5],['type'=>'cash','amount'=>20],['type'=>'supplier_ap','provider_id'=>$this->provider(),'amount'=>5]]])->assertCreated()->json('data.id');$this->postJson("/api/opening-balances/$id/validate")->assertOk();$this->postJson("/api/opening-balances/$id/post")->assertOk()->assertJsonPath('data.status','posted');$batch=DB::table('product_batches')->where('batch_number','OPEN-1')->first();$this->assertSame(10,$batch->quantity);$this->assertDatabaseHas('stock',['batch_id'=>$batch->id,'type'=>'OPENING_STOCK_IN','quantity'=>10]);$this->assertTrue(app(AccountingReportService::class)->trialBalance()['is_balanced']);$this->postJson("/api/opening-balances/$id/post")->assertStatus(500);}
 public function test_stock_count_and_manual_adjustment_are_locked_posted_and_accounted():void{[$p,$b]=$this->inventory(10,2);$count=$this->postJson('/api/stock-counts',['scope'=>'selected','product_ids'=>[$p->id]])->assertCreated()->json('data.count.id');$this->postJson("/api/stock-counts/$count/post",['lines'=>[['batch_id'=>$b->id,'counted_quantity'=>8,'reason'=>'count_difference']]])->assertOk();$this->assertDatabaseHas('stock',['batch_id'=>$b->id,'type'=>'ADJUSTMENT_OUT','quantity'=>2]);$this->postJson("/api/stock-counts/$count/post",['lines'=>[['batch_id'=>$b->id,'counted_quantity'=>8]]])->assertUnprocessable();$this->postJson('/api/stock-adjustments',['product_id'=>$p->id,'batch_id'=>$b->id,'quantity'=>3,'reason'=>'found_stock'])->assertCreated();$this->assertSame(11,(int)DB::table('product_batches')->where('id',$b->id)->value('quantity'));$this->assertTrue(app(AccountingReportService::class)->trialBalance()['is_balanced']);}
 public function test_quarantine_and_recall_are_excluded_from_pos_and_fefo():void{[$p,$b]=$this->inventory(5,2);$this->postJson("/api/batches/$b->id/state",['state'=>'quarantined','reason'=>'Inspection'])->assertOk();$this->getJson('/api/product/barcode/'.$p->barcode)->assertOk()->assertJsonCount(0,'data.available_batches');$this->postJson("/api/batches/$b->id/state",['state'=>'recalled','reason'=>'Manufacturer recall'])->assertOk();$this->assertDatabaseHas('batch_recalls',['batch_id'=>$b->id,'status'=>'active']);$this->postJson('/api/sales-invoices',['customer_id'=>$this->customer(),'date'=>now()->toDateString(),'discount'=>0,'paid_amount'=>0,'payment_method'=>'cash','items'=>[['product_id'=>$p->id,'amount'=>1,'price'=>5,'discount'=>0]]])->assertConflict();}
 public function test_branch_transfer_moves_stock_once_through_in_transit():void{$source=DB::table('branches')->insertGetId(['name'=>'Source','code'=>'SRC','created_at'=>now(),'updated_at'=>now()]);$destination=DB::table('branches')->insertGetId(['name'=>'Destination','code'=>'DST','created_at'=>now(),'updated_at'=>now()]);[$p,$b]=$this->inventory(10,2);DB::table('product_batches')->where('id',$b->id)->update(['branch_id'=>$source]);$id=$this->postJson('/api/stock-transfers',['source_branch_id'=>$source,'destination_branch_id'=>$destination,'lines'=>[['batch_id'=>$b->id,'quantity'=>4]]])->assertCreated()->json('data.transfer.id');$this->postJson("/api/stock-transfers/$id/send")->assertOk()->assertJsonPath('data.status','in_transit');$this->assertSame(6,(int)DB::table('product_batches')->where('id',$b->id)->value('quantity'));$this->assertDatabaseHas('stock',['reference_type'=>'stock_transfer','reference_id'=>$id,'type'=>'TRANSFER_OUT','quantity'=>4]);$this->postJson("/api/stock-transfers/$id/receive")->assertOk()->assertJsonPath('data.status','received');$this->assertSame(4,(int)DB::table('product_batches')->where(['product_id'=>$p->id,'branch_id'=>$destination])->value('quantity'));$this->postJson("/api/stock-transfers/$id/receive")->assertConflict();}
 private function inventory(int$q,float$c):array{$p=Product::factory()->create();$b=ProductBatch::create(['product_id'=>$p->id,'batch_number'=>fake()->unique()->numerify('ERP-####'),'expiry_date'=>now()->addYear(),'quantity'=>$q,'purchase_price'=>$c,'sale_price'=>5]);return[$p,$b];}
 private function provider():int{return DB::table('providers')->insertGetId(['name'=>'Opening Supplier','phone_num'=>fake()->unique()->numerify('######'),'city'=>'Test']);}
 private function customer():int{return DB::table('customers')->insertGetId(['name'=>'ERP Customer','phone_num'=>fake()->unique()->numerify('######'),'city'=>'Test']);}
}
